export const tfsaLossDefinitions={
  tfsaLoss:{title:'Separate a hypothetical TFSA value change from its room record',fields:[
    ['original','Single opening contribution, assumed already permitted (CAD)',10000,0,100000,1000],
    ['marketChange','Investment value change before the withdrawal (%)',-20,-80,80,5],
    ['withdrawShare','Ordinary withdrawal as a share of the resulting account value (%)',100,0,100,10],
    ['roomAfterContribution','Unused room across all TFSAs after that contribution (CAD)',0,0,100000,1000]
  ]}
};
export function tfsaLossCase(input,marketChange=input.marketChange,withdrawShare=input.withdrawShare){
  const value=input.original*(1+marketChange/100),change=value-input.original,withdrawal=Math.min(value,Math.max(0,value*withdrawShare/100));
  return {value,change,withdrawal,remaining:value-withdrawal,currentRoom:input.roomAfterContribution,nextSubtotal:input.roomAfterContribution+withdrawal,addbackDifference:withdrawal-input.original};
}
export function tfsaLossResult(kind,input){
  if(kind!=='tfsaLoss')throw Error('Unknown TFSA-loss topic.');
  const p=tfsaLossCase(input);
  return {metrics:[['Illustrated resources after the market move, before spending',p.value,'money'],['This ordinary withdrawal’s room addback next 1 January',p.withdrawal,'money'],['This withdrawal’s addback minus the original contribution',p.addbackDifference,'money']],note:'Original hypothetical nominal-CAD TFSA illustration using the ordinary-room framework in the cited CRA guidance, reviewed 25 October 2026. The opening contribution is assumed lawful and already completed; the separately entered unused room is the reconciled amount remaining across all the holder’s TFSAs afterward. The holder is assumed eligible and resident in Canada throughout the illustrated sequence. One investment-value change is followed by one ordinary withdrawal; proceeds remain as outside cash with no spending or further return. The investment-value change alters account value but not unused contribution room. The ordinary withdrawal’s amount is added back on 1 January of the next calendar year, not immediately. The next-year room chart is only carried unused room plus this withdrawal’s addback: it deliberately excludes the new annual dollar limit and every other transaction or adjustment, so it is not a full next-year room calculation. No actual contribution request, excess tax, fee, direct transfer, specified distribution, non-resident period, non-qualified investment or personal eligibility determination is modeled.',charts:[
    {id:'tfsa-loss-value-bridge',type:'waterfall',title:'A market loss changes account value without becoming a withdrawal',unit:'money',rows:[{label:'Opening contribution already made',value:input.original},{label:'Investment gain / loss',value:p.change}],totalLabel:'TFSA value before the withdrawal',note:'The investment change is a value movement inside the account, not a new deposit or money paid to the holder. It creates no withdrawal-based room addback. This bridge excludes every other asset, contribution, fee and transaction.'},
    {id:'tfsa-loss-financial-resources',type:'stackbar',title:'Withdrawing moves existing resources between locations',unit:'money',unitLabel:'Account value plus retained withdrawal cash, excluding contribution room (CAD)',seriesNames:['TFSA account value','Withdrawal cash retained outside'],rows:[{label:'After market move, before withdrawal',values:[p.value,0]},{label:'Immediately after ordinary withdrawal',values:[p.remaining,p.withdrawal]},{label:'Next 1 January, before any new action',values:[p.remaining,p.withdrawal]}],note:'The sum remains the same because the example assumes no spending, further market move or fees. Contribution room is permission to contribute and is not included as an asset. A calendar-year change in room does not by itself create more money or reverse an investment loss.'},
    {id:'tfsa-loss-room-events',type:'bar',title:'The room record follows contributions and ordinary withdrawals, not price changes',unit:'money',unitLabel:'Illustrated room subtotal; new annual dollar limit deliberately excluded (CAD)',rows:[{label:'After opening contribution',value:p.currentRoom},{label:'After investment value change',value:p.currentRoom},{label:'After ordinary withdrawal, same year',value:p.currentRoom},{label:'Next 1 January: unused plus addback',value:p.nextSubtotal}],note:'The first three bars retain the independently entered unused-room amount. On the next 1 January, the ordinary withdrawal adds its actual amount. This is a partial room ledger: it excludes the next annual limit, other accounts’ transactions and adjustments. It is not a statement of the holder’s complete room or permission to make a specific deposit.'},
    {id:'tfsa-loss-withdrawal-grid',type:'heatmap',title:'The withdrawal-based addback depends on the value actually taken out',unit:'money',unitLabel:'Room added next 1 January by the hypothetical ordinary withdrawal alone (CAD)',columns:['25% out','50% out','75% out','100% out'],rows:[-40,-20,0,20].map(marketChange=>({label:(marketChange>0?'+':'')+marketChange+'% move',values:[25,50,75,100].map(share=>tfsaLossCase(input,marketChange,share).withdrawal)})),note:'Rows replace the investment-value change and columns replace the share withdrawn. The opening contribution stays entered. Cells exclude carried unused room and the new annual dollar limit. The market move alone adds no room; each cell represents an actual ordinary withdrawal assumed after that move. These scenarios assign no probabilities and do not recommend a withdrawal.'}
  ]};
}
